namespace sv_f1270488052d4c4abf39100aa18a9cf7.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_f1270488052d4c4abf39100aa18a9cf7.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <ul class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    <span class="nav-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </li>
            }
        </ul>
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner"></div>
                <p>Loading settings…</p>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (_toastVisible)
        {
            <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastText
            </div>
        }
    </div>
</div>

@* ── Profile Section ── *@
@code {
    private RenderFragment RenderProfile() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>
            <p class="section-desc">Manage your personal information.</p>

            <div class="avatar-area">
                <div class="avatar-preview">
                    @if (!string.IsNullOrWhiteSpace(_profileDisplayName))
                    {
                        <img src="@_profileAvatarUrl" alt="Avatar" />
                    }
                    else
                    {
                        <div class="avatar-placeholder">?</div>
                    }
                </div>
                <div class="avatar-url-display">
                    <label>Avatar URL</label>
                    <span class="text-muted">@_profileAvatarUrl</span>
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control" @bind="_profileDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control" @bind="_profileEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4" @bind="_profileBio"></textarea>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Changes")
                </button>
                <button class="btn btn-outline" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };
}

@* ── Notifications Section ── *@
@code {
    private RenderFragment RenderNotifications() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-desc">Choose how you want to be notified.</p>

            <div class="toggle-group">
                <div class="toggle-row">
                    <label>Email Notifications</label>
                    <label class="switch">
                        <input type="checkbox" @bind="_notifEmail" />
                        <span class="slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Push Notifications</label>
                    <label class="switch">
                        <input type="checkbox" @bind="_notifPush" />
                        <span class="slider"></span>
                    </label>
                </div>
                <div class="toggle-row">
                    <label>Weekly Digest</label>
                    <label class="switch">
                        <input type="checkbox" @bind="_notifDigest" />
                        <span class="slider"></span>
                    </label>
                </div>
            </div>

            <h4 class="subsection-title">Muted Channels</h4>
            @if (_allChannels.Count == 0)
            {
                <p class="text-muted">No channels available.</p>
            }
            else
            {
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        var ch = channel;
                        <label class="channel-item">
                            <input type="checkbox"
                                   checked="@_mutedChannels.Contains(ch)"
                                   @onchange="e => ToggleMutedChannel(ch, (bool)e.Value!)" />
                            <span>@ch</span>
                        </label>
                    }
                </div>
            }

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save Preferences")
                </button>
            </div>
        </section>
    };
}

@* ── Security Section ── *@
@code {
    private RenderFragment RenderSecurity() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>
            <p class="section-desc">Manage passwords, two-factor authentication, and active sessions.</p>

            <!-- Change Password Panel -->
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPw">Current Password</label>
                            <input id="currentPw" type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPw">New Password</label>
                            <input id="newPw" type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPw">Confirm Password</label>
                            <input id="confirmPw" type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        @if (!string.IsNullOrEmpty(_passwordError))
                        {
                            <p class="field-error">@_passwordError</p>
                        }
                        <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                            @(_saving ? "Updating…" : "Update Password")
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Auth -->
            <div class="toggle-row" style="margin-top:1.5rem;">
                <div>
                    <label>Two-Factor Authentication</label>
                    <span class="status-badge @(_twoFactorEnabled ? "badge-on" : "badge-off")">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>

            @if (_securitySettings?.LastPasswordChange is not null)
            {
                <p class="text-muted" style="margin-top:0.5rem;">
                    Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </p>
            }

            <!-- Active Sessions -->
            <h4 class="subsection-title" style="margin-top:2rem;">Active Sessions</h4>
            @if (_securitySettings?.Sessions is { Count: > 0 })
            {
                <div class="table-wrapper">
                    <table class="data-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                var s = session;
                                <tr>
                                    <td>@s.Device</td>
                                    <td>@s.Location</td>
                                    <td>@s.LastActive.ToString("g")</td>
                                    <td>
                                        @if (s != _securitySettings.Sessions[0])
                                        {
                                            <button class="btn btn-danger btn-sm"
                                                    @onclick="() => PromptRevokeSession(s)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge-current">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="text-muted">No active sessions found.</p>
            }

            <!-- Revoke Confirmation Dialog -->
            @if (_sessionToRevoke is not null)
            {
                <div class="modal-backdrop" @onclick="() => _sessionToRevoke = null">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h4>Revoke Session</h4>
                        <p>
                            Are you sure you want to revoke the session on
                            <strong>@_sessionToRevoke.Device</strong> (@_sessionToRevoke.Location)?
                        </p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="ConfirmRevokeSession" disabled="@_saving">
                                @(_saving ? "Revoking…" : "Revoke")
                            </button>
                            <button class="btn btn-outline" @onclick="() => _sessionToRevoke = null">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* ── Appearance Section ── *@
@code {
    private RenderFragment RenderAppearance() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-desc">Customize the look and feel of the application.</p>

            <h4 class="subsection-title">Theme</h4>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    var t = theme;
                    <label class="radio-item">
                        <input type="radio" name="theme" value="@t"
                               checked="@(_appearTheme == t)"
                               @onchange="() => _appearTheme = t" />
                        <span>@t</span>
                    </label>
                }
            </div>

            <h4 class="subsection-title">Font Size</h4>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    var sz = size;
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@sz"
                               checked="@(_appearFontSize == sz)"
                               @onchange="() => _appearFontSize = sz" />
                        <span>@sz</span>
                    </label>
                }
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-control" @bind="_appearLanguage">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="toggle-row">
                <label>Compact Mode</label>
                <label class="switch">
                    <input type="checkbox" @bind="_appearCompact" />
                    <span class="slider"></span>
                </label>
            </div>

            <!-- Live Preview -->
            <h4 class="subsection-title" style="margin-top:1.5rem;">Preview</h4>
            <div class="live-preview @GetPreviewClasses()">
                <div class="preview-header">
                    <strong>Dashboard</strong>
                    <span class="preview-badge">3 new</span>
                </div>
                <p class="preview-text">
                    This is a preview of your selected appearance settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <div class="preview-actions">
                    <span class="preview-btn primary">Action</span>
                    <span class="preview-btn secondary">Cancel</span>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save")
                </button>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_appearTheme switch
        {
            "Dark" => "preview-dark",
            "System" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_appearFontSize switch
        {
            "Small" => "preview-font-sm",
            "Large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (_appearCompact) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }
}

@* ── Component State & Logic ── *@
@code {
    // Navigation
    private record SectionDef(string Key, string Label, string Icon);
    private readonly List<SectionDef> _sections = new()
    {
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    };
    private string ActiveSection { get; set; } = "profile";

    // Shared state
    private bool _loading = true;
    private bool _saving;
    private bool _toastVisible;
    private bool _toastIsError;
    private string _toastText = "";
    private CancellationTokenSource? _toastCts;

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notification state
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new() { "general", "announcements", "random", "engineering", "design" };

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _appearTheme = "Light";
    private string _appearFontSize = "Medium";
    private string _appearLanguage = "en";
    private bool _appearCompact;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var profileTask = SettingsService.GetProfileAsync();
            var notifTask = SettingsService.GetNotificationPrefsAsync();
            var securityTask = SettingsService.GetSecuritySettingsAsync();
            var appearanceTask = SettingsService.GetAppearanceAsync();

            await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

            var profile = profileTask.Result;
            _savedProfile = profile;
            ApplyProfile(profile);

            var notifs = notifTask.Result;
            _notifEmail = notifs.EmailNotifications;
            _notifPush = notifs.PushNotifications;
            _notifDigest = notifs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(notifs.MutedChannels);

            _securitySettings = securityTask.Result;
            _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

            var appearance = appearanceTask.Result;
            _appearTheme = appearance.Theme;
            _appearFontSize = appearance.FontSize;
            _appearLanguage = appearance.Language;
            _appearCompact = appearance.CompactMode;
        }
        catch
        {
            ShowToast("Failed to load settings.", isError: true);
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // ── Profile actions ──

    private async Task SaveProfile()
    {
        _saving = true;
        try
        {
            var updated = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
            await SettingsService.SaveProfileAsync(updated);
            _savedProfile = updated;
            ShowToast("Profile saved successfully.");
        }
        catch
        {
            ShowToast("Failed to save profile.", isError: true);
        }
        finally { _saving = false; }
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
            ShowToast("Changes discarded.");
        }
    }

    // ── Notification actions ──

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        try
        {
            var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifDigest, _mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            ShowToast("Notification preferences saved.");
        }
        catch
        {
            ShowToast("Failed to save preferences.", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Security actions ──

    private async Task UpdatePassword()
    {
        _passwordError = "";
        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword) ||
            string.IsNullOrWhiteSpace(_confirmPassword))
        {
            _passwordError = "All fields are required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordPanelOpen = false;
            ShowToast("Password updated successfully.");
        }
        catch
        {
            ShowToast("Failed to update password.", isError: true);
        }
        finally { _saving = false; }
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        _saving = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = _securitySettings! with
            {
                Sessions = _securitySettings.Sessions.Where(s => s.Id != _sessionToRevoke.Id).ToList()
            };
            ShowToast("Session revoked.");
            _sessionToRevoke = null;
        }
        catch
        {
            ShowToast("Failed to revoke session.", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Appearance actions ──

    private async Task SaveAppearance()
    {
        _saving = true;
        try
        {
            var settings = new AppearanceSettings(_appearTheme, _appearFontSize, _appearLanguage, _appearCompact);
            await SettingsService.SaveAppearanceAsync(settings);
            ShowToast("Appearance settings saved.");
        }
        catch
        {
            ShowToast("Failed to save appearance settings.", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Toast ──

    private void ShowToast(string text, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastText = text;
        _toastIsError = isError;
        _toastVisible = true;
        _ = DismissToastAfterDelay(_toastCts.Token);
    }

    private async Task DismissToastAfterDelay(CancellationToken ct)
    {
        try
        {
            await Task.Delay(3000, ct);
            _toastVisible = false;
            await InvokeAsync(StateHasChanged);
        }
        catch (TaskCanceledException) { }
    }
}

