                               @onchange="() => _appearTheme = t" />
                        <span>@t</span>
                    </label>
                }
            </div>

            <h4 class="subsection-title">Font Size</h4>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    var sz = size;
                    <label class="radio-item">
                        <input type="radio" name="fontSize" value="@sz"
                               checked="@(_appearFontSize == sz)"
                               @onchange="() => _appearFontSize = sz" />
                        <span>@sz</span>
                    </label>
                }
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-control" @bind="_appearLanguage">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="toggle-row">
                <label>Compact Mode</label>
                <label class="switch">
                    <input type="checkbox" @bind="_appearCompact" />
                    <span class="slider"></span>
                </label>
            </div>

            <!-- Live Preview -->
            <h4 class="subsection-title" style="margin-top:1.5rem;">Preview</h4>
            <div class="live-preview @GetPreviewClasses()">
                <div class="preview-header">
                    <strong>Dashboard</strong>
                    <span class="preview-badge">3 new</span>
                </div>
                <p class="preview-text">
                    This is a preview of your selected appearance settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <div class="preview-actions">
                    <span class="preview-btn primary">Action</span>
                    <span class="preview-btn secondary">Cancel</span>
                </div>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save")
                </button>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add(_appearTheme switch
        {
            "Dark" => "preview-dark",
            "System" => "preview-system",
            _ => "preview-light"
        });
        classes.Add(_appearFontSize switch
        {
            "Small" => "preview-font-sm",
            "Large" => "preview-font-lg",
            _ => "preview-font-md"
        });
        if (_appearCompact) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }
}

@* ── Component State & Logic ── *@
@code {
    // Navigation
    private record SectionDef(string Key, string Label, string Icon);
    private readonly List<SectionDef> _sections = new()
    {
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    };
    private string ActiveSection { get; set; } = "profile";

    // Shared state
    private bool _loading = true;
    private bool _saving;
    private bool _toastVisible;
    private bool _toastIsError;
    private string _toastText = "";
    private CancellationTokenSource? _toastCts;

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notification state
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _allChannels = new() { "general", "announcements", "random", "engineering", "design" };

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _appearTheme = "Light";
    private string _appearFontSize = "Medium";
    private string _appearLanguage = "en";
    private bool _appearCompact;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var profileTask = SettingsService.GetProfileAsync();
            var notifTask = SettingsService.GetNotificationPrefsAsync();
            var securityTask = SettingsService.GetSecuritySettingsAsync();
            var appearanceTask = SettingsService.GetAppearanceAsync();

            await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

            var profile = profileTask.Result;
            _savedProfile = profile;
            ApplyProfile(profile);

            var notifs = notifTask.Result;
            _notifEmail = notifs.EmailNotifications;
            _notifPush = notifs.PushNotifications;
            _notifDigest = notifs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(notifs.MutedChannels);

            _securitySettings = securityTask.Result;
            _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

            var appearance = appearanceTask.Result;
            _appearTheme = appearance.Theme;
            _appearFontSize = appearance.FontSize;
            _appearLanguage = appearance.Language;
            _appearCompact = appearance.CompactMode;
        }
        catch
        {
            ShowToast("Failed to load settings.", isError: true);
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // ── Profile actions ──

    private async Task SaveProfile()
    {
        _saving = true;
        try
        {
            var updated = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
            await SettingsService.SaveProfileAsync(updated);
            _savedProfile = updated;
            ShowToast("Profile saved successfully.");
        }
        catch
        {
            ShowToast("Failed to save profile.", isError: true);
        }
        finally { _saving = false; }
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
            ShowToast("Changes discarded.");
        }
    }

    // ── Notification actions ──

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        _saving = true;
        try
        {
            var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifDigest, _mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            ShowToast("Notification preferences saved.");
        }
        catch
        {
            ShowToast("Failed to save preferences.", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Security actions ──

    private async Task UpdatePassword()
    {
        _passwordError = "";
        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword) ||
            string.IsNullOrWhiteSpace(_confirmPassword))
        {
            _passwordError = "All fields are required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordPanelOpen = false;
            ShowToast("Password updated successfully.");
        }
        catch
        {
            ShowToast("Failed to update password.", isError: true);
        }
        finally { _saving = false; }
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is null) return;
        _saving = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = _securitySettings! with
            {
                Sessions = _securitySettings.Sessions.Where(s => s.Id != _sessionToRevoke.Id).ToList()
            };
            ShowToast("Session revoked.");
            _sessionToRevoke = null;
        }
        catch
        {
            ShowToast("Failed to revoke session.", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Appearance actions ──

    private async Task SaveAppearance()
    {
        _saving = true;
        try
        {
            var settings = new AppearanceSettings(_appearTheme, _appearFontSize, _appearLanguage, _appearCompact);
            await SettingsService.SaveAppearanceAsync(settings);
            ShowToast("Appearance settings saved.");
        }
        catch
        {
            ShowToast("Failed to save appearance settings.", isError: true);
        }
        finally { _saving = false; }
    }

    // ── Toast ──

    private void ShowToast(string text, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastText = text;
        _toastIsError = isError;
        _toastVisible = true;
        _ = DismissToastAfterDelay(_toastCts.Token);
    }

    private async Task DismissToastAfterDelay(CancellationToken ct)
    {
        try
        {
            await Task.Delay(3000, ct);
            _toastVisible = false;
            await InvokeAsync(StateHasChanged);
        }
        catch (TaskCanceledException) { }
    }
}
"}

